// One item per tool call in Vapi's request, after checking the shared secret header.
const req = $("Vapi Tool Request").first().json;
const settings = Object.fromEntries($("Read Settings").all().map(i => [i.json.key, i.json.value ?? ""]));
const key = (req.headers ?? {})["x-fernhollow-key"] ?? "";
if (!settings.webhook_secret || key !== settings.webhook_secret) return [{ json: { authorized: false } }];

const msg = req.body?.message ?? {};
const call = msg.call ?? {};
const list = Array.isArray(msg.toolCallList) && msg.toolCallList.length
  ? msg.toolCallList
  : (msg.toolWithToolCallList ?? []).map(t => t.toolCall).filter(Boolean);

const items = list.map(c => {
  let args = c.function?.arguments ?? c.arguments ?? {};
  if (typeof args === "string") { try { args = JSON.parse(args); } catch (e) { args = {}; } }
  return {
    json: {
      authorized: true,
      tool_call_id: c.id,
      name: c.function?.name ?? c.name ?? "",
      args,
      caller_number: call.customer?.number ?? msg.customer?.number ?? "",
      call_id: call.id ?? "",
      call_type: call.type ?? "",
      calendar_id: settings.calendar_id,
      sheet_id: settings.sheet_id,
      staff_chat_id: settings.staff_chat_id,
    },
  };
});
return items.length ? items : [{ json: { authorized: true, empty: true } }];

// Vapi wants { results: [{ toolCallId, result }] } with each result a flat, one-line string.
const calls = $("Unpack Calls").all().map(i => i.json).filter(c => c.tool_call_id);
const byId = Object.fromEntries($input.all().map(i => i.json).filter(r => r && r.tool_call_id).map(r => [r.tool_call_id, r]));
const fallback = "The scheduling system didn't respond. Apologize briefly and offer to take a message for the front desk.";
const results = calls.map(c => {
  const r = byId[c.tool_call_id];
  const text = r && typeof r.result === "string" && r.result.trim() ? r.result : fallback;
  return { name: c.name, toolCallId: c.tool_call_id, result: text.replace(/\s*\n\s*/g, " ").trim() };
});
return [{ json: { results } }];
